import type { components } from './api'

type Schemas = components['schemas']

/**
 * springdoc marks response properties optional, but the API always returns most of them.
 * These aliases restore the real contract: only genuinely nullable fields stay optional.
 * (api.ts is generated by `npm run gen:api` and must never be edited by hand.)
 */
export type Role = 'ADMIN' | 'RECRUITER' | 'INTERVIEWER'
export type UserSummary = Required<Schemas['UserSummary']>
export type LoginResponse = Required<Omit<Schemas['LoginResponse'], 'user'>> & { user: UserSummary }
export type UserView = Required<Omit<Schemas['UserView'], 'lastLoginAt'>> & { lastLoginAt?: string }
export type PageResponse<T> = { content: T[]; page: number; size: number; totalElements: number; totalPages: number }

export type CandidateSource = NonNullable<Schemas['CandidateView']['source']>
export type CandidateStatus = NonNullable<Schemas['CandidateView']['status']>
export type SkillLevel = NonNullable<Schemas['SkillEntryView']['level']>
export type LegalBasis = NonNullable<Schemas['ConsentView']['legalBasis']>

export type SkillView = Required<Omit<Schemas['SkillView'], 'category'>> & { category?: string }

export type SkillEntryView = Required<Omit<Schemas['SkillEntryView'], 'years' | 'level'>> &
  Pick<Schemas['SkillEntryView'], 'years' | 'level'>

export type ConsentView = Required<Pick<Schemas['ConsentView'], 'legalBasis' | 'givenAt'>> &
  Pick<Schemas['ConsentView'], 'expiresAt' | 'evidence' | 'withdrawnAt'>

type CandidateOptional = 'phone' | 'currentTitle' | 'currentCompany' | 'location' | 'yearsExperience' | 'summary' | 'linkedinUrl'
export type CandidateView = Required<Omit<Schemas['CandidateView'], CandidateOptional | 'skills' | 'consent'>> &
  Pick<Schemas['CandidateView'], CandidateOptional> & { skills: SkillEntryView[]; consent?: ConsentView }

type SummaryOptional = 'currentTitle' | 'location' | 'yearsExperience' | 'ownerName'
export type CandidateSummary = Required<Omit<Schemas['CandidateSummary'], SummaryOptional>> &
  Pick<Schemas['CandidateSummary'], SummaryOptional>

export type NoteView = Required<Schemas['NoteView']>

export type JobStatus = NonNullable<Schemas['JobView']['status']>
export type EmploymentType = NonNullable<Schemas['JobView']['employmentType']>
export type SkillImportance = NonNullable<Schemas['JobSkillView']['importance']>
export type ApplicationStatus = NonNullable<Schemas['ApplicationView']['status']>
export type RejectionReason = NonNullable<Schemas['ApplicationView']['rejectionReason']>

export type ClientView = Required<Omit<Schemas['ClientView'], 'industry' | 'contactName' | 'contactEmail'>> &
  Pick<Schemas['ClientView'], 'industry' | 'contactName' | 'contactEmail'>

export type JobSkillView = Required<Omit<Schemas['JobSkillView'], 'minYears'>> & Pick<Schemas['JobSkillView'], 'minYears'>

type JobViewOptional = 'description' | 'location' | 'salaryMin' | 'salaryMax' | 'currency' | 'openedAt' | 'closedAt'
export type JobView = Required<Omit<Schemas['JobView'], JobViewOptional | 'skills'>> &
  Pick<Schemas['JobView'], JobViewOptional> & { skills: JobSkillView[] }

export type JobSummary = Required<Omit<Schemas['JobSummary'], 'location'>> & Pick<Schemas['JobSummary'], 'location'>

type ApplicationOptional = 'candidateEmail' | 'candidateTitle' | 'clientName' | 'rejectionReason'
export type ApplicationView = Required<Omit<Schemas['ApplicationView'], ApplicationOptional>> &
  Pick<Schemas['ApplicationView'], ApplicationOptional>

export type StatusChangeResult = { application: ApplicationView; jobCloseSuggested: boolean }
export type StageView = { status: ApplicationStatus; count: number; applications: ApplicationView[] }
export type PipelineView = {
  jobId: string
  jobTitle: string
  clientName: string
  jobStatus: JobStatus
  openings: number
  hired: number
  stages: StageView[]
}
